                <SelectionList
                    sections={[{data: items}]}
                    ListItem={RadioListItem}
                    onSelectRow={changeRole}
                    shouldSingleExecuteRowSelect
                    initiallyFocusedOptionKey={items.find((item) => item.isSelected)?.keyForList}
